<?php require_once __DIR__.'/includes/bootstrap.php';$id=(int)($_GET['id']??0);$s=db()->prepare('SELECT a.*,m.construction_project_id FROM construction_message_attachments a JOIN construction_messages m ON m.id=a.message_id WHERE a.id=?');$s->execute([$id]);$f=$s->fetch();if(!$f||!dev_can_access((int)$f['construction_project_id'])){http_response_code(404);exit('File not found.');}$path=__DIR__.'/../'.$f['file_path'];if(!is_file($path)){http_response_code(404);exit('File not found.');}header('Content-Type: '.$f['mime_type']);header('Content-Length: '.filesize($path));header('Content-Disposition: inline; filename="'.basename($f['original_name']).'"');readfile($path);
